function start(){if(started)return;started=true;document.querySelector('#startPanel').style.opacity=0;setTimeout(()=>document.querySelector('#startPanel').remove(),600);ui.title.style.opacity=0;notify('Bem-vindo ao Vale dos Ecos, shinobi!');document.body.requestPointerLock?.()}
