function use(key){let t=performance.now()/1000;if(t-lastAction[key]<(key==='q'?4:key==='e'?2.4:9))return;let cost=key==='q'?13:key==='e'?20:42;if(chakra<cost){notify('Energia espiritual insuficiente');return}chakra-=cost;lastAction[key]=t;
if(key==='q'){let dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));player.position.addScaledVector(dir,5.4);player.position.y=Math.max(0,player.position.y);avatar.rotation.x=-.25;setTimeout(()=>avatar.rotation.x=0,250);burst(player.position.clone().add(new THREE.Vector3(0,1,0)),0x60ffe3,1.6);if(mode==='race')checkRace()}
if(key==='e'){let dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));let ball=new THREE.Mesh(new THREE.SphereGeometry(.35,16,12),new THREE.MeshBasicMaterial({color:0x8bf8ec}));ball.position.copy(player.position).add(new THREE.Vector3(0,1.5,0)).addScaledVector(dir,.9);scene.add(ball);let glow=new THREE.PointLight(0x64ffe6,1.5,5);ball.add(glow);attackBalls.push({ball,dir,life:2.2});burst(player.position.clone().add(new THREE.Vector3(0,1.4,0)),0x8effed,.55)}
if(key==='r'){burst(player.position.clone().add(new THREE.Vector3(0,1,0)),0xb390ff,5);for(let t of targets){if(!t.hit&&t.group.position.distanceTo(player.position)<9)hitTarget(t)}for(let s of shards){if(!s.got&&s.gem.position.distanceTo(player.position)<7)collect(s)}notify('EXPANSÃO ESPIRITUAL!')}
}
function burst(pos,color,size){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.5,16,12),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.55,wireframe:true}));mesh.position.copy(pos);scene.add(mesh);let st=performance.now();function anim(){let p=(performance.now()-st)/420;if(p>1){scene.remove(mesh);return}mesh.scale.setScalar(1+p*size);mesh.material.opacity=.55*(1-p);requestAnimationFrame(anim)}anim()}
function hitTarget(t){t.hit=true;t.group.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.color.set(0x59666e);o.material.transparent=true;o.material.opacity=.28}});t.mark.o.material.opacity=.15;targetsHit++;fragments+=2;refresh();burst(t.group.position.clone().add(new THREE.Vector3(0,2,0)),0xff8791,1.2);if(mode==='targets'&&targetsHit>=5){mode='explore';quest('Desafio concluído!','Você acertou todos os alvos. +10 fragmentos','DESAFIO COMPLETO');fragments+=10;refresh();notify('Treino completo! +10 fragmentos')}}
function collect(s){s.got=true;scene.remove(s.gem);scene.remove(s.glow);fragments++;refresh();burst(s.home,0x76ffe1,.8);if(mode==='seals'){sealCount++;quest(`Colete os selos · ${sealCount}/6`,'Os selos espirituais brilham pelo vale. Continue!','PROVA DOS SELOS');if(sealCount>=6){mode='explore';fragments+=12;refresh();quest('Prova dos selos concluída','Você provou sua sintonia espiritual. +12 fragmentos','DESAFIO COMPLETO');notify('Prova concluída! +12 fragmentos')}}}
function interact(){if(mode!=='explore'){notify('Termine o desafio atual primeiro');return}const d=player.position.distanceTo(guardian.group.position);if(d<4.2){mode='seals';sealCount=0;timer=65;quest('Colete os selos · 0/6','Encontre 6 fragmentos brilhantes em 65 segundos!','MINIJOGO · PROVA DOS SELOS');notify('Minijogo iniciado: Prova dos Selos!');return}if(player.position.distanceTo(new THREE.Vector3(21,0,-4))<5){mode='targets';targetsHit=targets.filter(t=>t.hit).length;if(targetsHit>=5){targets.forEach(t=>{t.hit=false;t.group.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.color.set(t.group.children[0]===o?0x79513d:0x829694);o.material.opacity=1}});t.mark.o.material.opacity=.9});targetsHit=0}quest('Treino dos ecos · '+targetsHit+'/5','Use E para lançar orbes ou R para expansão. Acerte os 5 alvos!','MINIJOGO · PRECISÃO');notify('Treino iniciado! Acerte os alvos com E ou R.');return}if(player.position.distanceTo(new THREE.Vector3(-21,0,-12))<5){mode='race';raceIndex=0;raceRings.forEach(r=>{r.done=false;r.ring.material.opacity=.9});quest('Corrida dos ecos · 0/7','Atravesse os arcos dourados. Use Q para ganhar velocidade!','MINIJOGO · CORRIDA');notify('Corrida iniciada! Siga os arcos dourados.');checkRace();return}if(player.position.distanceTo(new THREE.Vector3(0,0,-34))<10){notify('O santuário guarda técnicas antigas... volte após dominar os desafios.');return}notify('Não há nada para interagir aqui.')}
function checkRace(){while(raceIndex<raceRings.length){let r=raceRings[raceIndex];if(player.position.distanceTo(new THREE.Vector3(r.x,0,r.z))<2.8){r.done=true;r.ring.material.opacity=.2;raceIndex++;fragments++;refresh()}else break}if(raceIndex>=raceRings.length&&mode==='race'){mode='explore';fragments+=14;refresh();quest('Corrida concluída!','Você cruzou os 7 arcos em velocidade shinobi. +14 fragmentos','DESAFIO COMPLETO');notify('Corrida perfeita! +14 fragmentos')}}
addEventListener('keydown',e=>{if(e.code==='KeyF'&&started)interact()});

